  "proverbs.principle": "Go principle",
  "proverbs.proverb": "Go proverb",
  "proverbs.sun": "(Sun Tzu, The Art of War)",
  "proverbs.rules": "(Ten Golden Rules of Go)",
  "proverbs.line": "{label}: \"{text}\" {source}. {link}",
  "proverbs.master": "Go master",
  "proverbs.attributed": "(attributed to {name})",
  "proverbs.line-master": "{label}: \"{text}\" {source}. {link}",
  "proverbs.line-plain": "{label}: \"{text}\" {link}",
  "proverbs.sacrifice.text": "Sacrifice stones to gain the initiative.",
  "proverbs.sacrifice.link": "A gives up a stone, but what it gains elsewhere is worth more.",
  "proverbs.rescue.text": "Don’t go fishing while your house is on fire.",
  "proverbs.rescue.link": "Saving your own group comes before taking points elsewhere: B leaves it to die.",
  "proverbs.kill.text": "In war, the way is to avoid what is strong and to strike at what is weak.",
  "proverbs.kill.link": "The weak group is the target: A catches it, B lets it get away.",
  "proverbs.lost.text": "Enter the opponent’s sphere gently.",
  "proverbs.lost.link": "A stone played too deep into the opponent’s area has no room to live, so B only feeds the opponent.",
  "proverbs.punished.text": "Be careful; do not move rashly.",
  "proverbs.punished.link": "B leaves a cutting point the opponent can use straight away.",
  "proverbs.whole.text": "The best thing of all is to take the enemy’s country whole and intact; to shatter and destroy it is not so good.",
  "proverbs.whole.link": "A gains more by building than B gains by attacking.",
  "proverbs.big.text": "Give up the small to take the large.",
  "proverbs.big.link": "Both moves have a point, but the area A claims is worth more.",
  "proverbs.whole.master.text": "Go is harmony.",
  "proverbs.whole.master.name": "Go Seigen",
  "proverbs.whole.master.link": "A builds in balance with the whole board; B attacks for its own sake and gains less.",
  "proverbs.lost.master.text": "Match strength with strength, lightness with lightness.",
  "proverbs.lost.master.name": "Cho Chikun",
  "proverbs.lost.master.link": "Against the opponent’s strength, play lightly: B plunges in heavily where it cannot live.",
  "proverbs.big.master.text": "The Go board is so much larger than the Chess board that a defeat on one wing of the battle-field can often be compensated by victory on another.",
  "proverbs.big.master.name": "Edward Lasker",
  "proverbs.big.master.source": "(Edward Lasker, Go and Go-Moku, 1960, page 100)",
  "proverbs.big.master.link": "Think of the whole battlefield: the ground A claims is worth more than what B fights for.",
  "proverbs.whole.master2.label": "Go teaching",
  "proverbs.whole.master2.text": "Go is often called the ‘art of harmony.’ As it is a contest for victory between two players, a self-centered way of thinking often leads to self ruin.",
  "proverbs.whole.master2.source": "(The Nihon Ki-in, Go: The World’s Most Fascinating Game, 1973)",
  "proverbs.whole.master2.link": "A builds without overreaching; B thinks only of its own attack, and gains less.",
  "proverbs.lost.master2.text": "The fighting can rage around this group, but it will stand steady as a rock, and black stones may crash in ruin against it.",
  "proverbs.lost.master2.source": "(Kaoru Iwamoto, Go for Beginners, 1972, page 105, on thickness)",
  "proverbs.lost.master2.link": "Stay away from the opponent’s strength: B crashes into it and cannot live.",
  "proverbs.kill.master.text": "In go the best moves tend to be those which serve more than one purpose, and the fastest way to build territory is to do so while attacking.",
  "proverbs.kill.master.source": "(Kaoru Iwamoto, Go for Beginners, 1972, page 104)",
  "proverbs.kill.master.link": "A attacks the weak group and gains ground at the same time; B lets it go.",
  "proverbs.kill.master2.label": "Go stratagem",
  "proverbs.kill.master2.text": "Loot a burning house.",
  "proverbs.kill.master2.source": "(The Thirty-Six Stratagems, as applied to Go by Ma Xiaochun 9-dan)",
  "proverbs.kill.master2.link": "While the opponent’s group is in crisis, A takes the profit; B lets the moment pass.",
  "proverbs.sacrifice.master.label": "Go stratagem",
  "proverbs.sacrifice.master.text": "Sacrifice plums for peaches.",
  "proverbs.sacrifice.master.source": "(The Thirty-Six Stratagems, as applied to Go by Ma Xiaochun 9-dan)",
  "proverbs.sacrifice.master.link": "A gives up the lesser stones to keep what matters more.",
  "proverbs.punished.master.text": "To make every move be the most efficient is to say to run in front of your opponent on every move. Thus, one or two spots would naturally become thin.",
  "proverbs.punished.master.source": "(Sakata Eio, in Go on Go: The Analyzed Games of Go Seigen, page 133)",
  "proverbs.punished.master.link": "B reaches too far and leaves a thin spot the opponent can use straight away.",
